local UIModule          = CS.Engine.UI.UIModule
---@type ActivityUtils
local ActivityUtils     = import("Game.Activity.ActivityUtils")
--- from: Assets/BundleResources/Prefabs/Activity/LadderCompetionEntryDialog.prefab
---@class CompeteEntryNode
---@field Env                           	CompeteEntryNode
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field TextLeftTime                  	UnityEngine.RectTransform
---@field TextActivityTime              	UnityEngine.RectTransform
---@field TextActivityDesc              	UnityEngine.RectTransform
---@field BtnEntry                      	UnityEngine.RectTransform
local CompeteEntryNode = Class('CompeteEntryNode')

local cs_coroutine = require('XLua.cs_coroutine')
local Yielders = CS.Engine.Lib.Yielders
function CompeteEntryNode:__init()
    ---@type ActivityDojo
    self.activityDojo_ = nil
    self.isRequestHome = false
    self.updateCo = nil
end


function CompeteEntryNode:__delete()
    self.activityDojo_ = nil
    self.isRequestHome = nil
    if not isNull(self.updateCo) then
        cs_coroutine.stop(self.updateCo)
        self.updateCo = nil
    end
end


function CompeteEntryNode:Awake()
    SetButtonAction(self.BtnEntry, Bind(self, self.OnClickEntryButtonHandler_))
end


function CompeteEntryNode:OnDestroy()
    self.controller = nil -- luaBehaviour 中 CSharp 对象
    self:Delete()
end


---@param actDojo ActivityDojo
function CompeteEntryNode:Refresh(actDojo)
    if not actDojo then return end
    self.activityDojo_ = actDojo
    self:UpdateView_()
    self:RequestHome()
end

function CompeteEntryNode:RequestHome()
    GameUtils.Request(Interfaces.ActivityUserPkHome, { activityUuid = self.activityDojo_.id }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local data = response.data
            data.activityUuid = self.activityDojo_.id
            GameUtils.RemoveEntityCompByType(ECSComponentType.Constants.CompeteComponent)
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CompeteComponent)
            comp:Initial(data)
            self.isRequestHome = true
        end
    end)
end


function CompeteEntryNode:UpdateView_()
    -- update time
    CfUtils.FillText(self.TextActivityTime, ActivityUtils.ConventActivityDurationTime(self.activityDojo_.startTime, self.activityDojo_.endTime))

    -- update descr
    CfUtils.FillText(self.TextActivityDesc, self.activityDojo_.detail)
    local t = checkTable(self.activityDojo_.unlock)
    if table.count(t) > 0 then
        local vo = t[1]
        local isUnlock = GameUtils.IsUnlockedSingle(vo.targetType, vo.targetNum, vo.targetId)
        local entryLockGroupTrans = self.BtnEntry.transform.parent:Find("EntryLockGroup")
        if entryLockGroupTrans then
            CfUtils.SetActive(entryLockGroupTrans, not isUnlock)
            local err = GameUtils.GetUnlockDescr(vo.targetType, vo.targetNum, vo.targetId)
            SetButtonAction(entryLockGroupTrans:Find("BtnEntryLock"), function()
                GameUtils.Toast(localize('_name_解锁', {_name_ = tostring(err)}))
            end)
            CfUtils.FillText(entryLockGroupTrans:Find("UnlockCondition/Text"),  localize('_name_解锁', {_name_ = tostring(err)}))
        end
        CfUtils.SetActive(self.BtnEntry, isUnlock)
    end
    if not isNull(self.updateCo) then
        cs_coroutine.stop(self.updateCo)
        self.updateCo = nil
    end
    self.updateCo = cs_coroutine.start(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.6))
        local titleImgUrl = checkString(self.activityDojo_.titleImage)
        if string.len(titleImgUrl) > 0 then
            CfUtils.FillWebRawImage(self.ImgTitleName, titleImgUrl)
        end
    end)
    -- update redPoint
    ActivityUtils.UpdateActivityMainRedPointState(self.activityDojo_.id, self.activityDojo_.redDotHint)
end



function CompeteEntryNode:ClearCountdown_()
end


function CompeteEntryNode:OnClickEntryButtonHandler_()
    if not self.isRequestHome then
        return
    end
    if self.activityDojo_ then
        local t = checkTable(self.activityDojo_.unlock)
        if table.count(t) > 0 then
            local vo = t[1]
            local isUnlock = GameUtils.IsUnlockedSingle(vo.targetType, vo.targetNum, vo.targetId)
            if not isUnlock then
                local err = GameUtils.GetUnlockDescr(vo.targetType, vo.targetNum, vo.targetId)
                GameUtils.Toast(err)
                return
            end
        end
        ---@type CompeteComponent
        local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CompeteComponent)
        local prefabConf = comp:GetPrefabDialogConf()
        local peopleId = comp:GetPlayerPeopleId()
        if checkInt(peopleId) > 0  then
            UIModule.OpenDialog(
                    { id = prefabConf.MAIN_DIALOG, parameters = { activityDojo = self.activityDojo_ } },
                    { { id = Constants.UITypeIds.UIActivityMainDialog } }
            )
        else
            if comp:IsActivityEnd() then
                GameUtils.Toast(localize("活动已结束"))
                return
            end
            UIModule.OpenDialog(
                    { id = prefabConf.CHOOSE_ROLE, parameters = { activityDojo = self.activityDojo_ } },
                    { { id = Constants.UITypeIds.UIActivityMainDialog } }
            )
        end
    else
        GameUtils.Toast(localize("活动不存在"))
    end
end
return CompeteEntryNode
